29	
30	import org.slf4j.Logger;
31	import org.slf4j.LoggerFactory;
32	import org.springframework.http.HttpHeaders;
33	import org.springframework.http.HttpStatus;
34	import org.springframework.http.ResponseEntity;
35	import org.springframework.samples.petclinic.rest.advice.CityOwnerLimitException;
36	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
37	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
39	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
40	import org.springframework.samples.petclinic.mapper.OwnerMapper;
41	import org.springframework.samples.petclinic.mapper.PetMapper;
42	import org.springframework.samples.petclinic.mapper.VisitMapper;
43	import org.springframework.samples.petclinic.model.Owner;
44	import org.springframework.samples.petclinic.model.Pet;
45	import org.springframework.samples.petclinic.model.Visit;
46	import org.springframework.samples.petclinic.rest.api.OwnersApi;
47	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
48	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.PetDto;
50	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitDto;
52	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
53	import org.springframework.samples.petclinic.service.ClinicService;
54	import org.springframework.security.access.prepost.PreAuthorize;
55	import org.springframework.util.StringUtils;
56	import org.springframework.web.bind.annotation.CrossOrigin;
57	import org.springframework.web.bind.annotation.RequestMapping;
58	import org.springframework.web.bind.annotation.RestController;
59	import org.springframework.web.util.UriComponentsBuilder;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
74	     * owner's id, customer code, registration date and membership level, so the create side-effect
75	     * can be audited independently of the application log.
76	     */
77	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
78	
79	    private final ClinicService clinicService;
80	
81	    private final OwnerMapper ownerMapper;
82	
83	    private final PetMapper petMapper;
84	
85	    private final VisitMapper visitMapper;
86	
87	    /**
88	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
89	     * and a domain containing at least one dot, with no whitespace in any segment.
90	     */
91	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
92	
93	    /**
94	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
95	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
96	     */
97	    private static final int MAX_OWNERS_PER_CITY = 50;
98	
99	    /**
100	     * Maximum number of owners that may be registered on a single day (by registration date). A create
101	     * attempted once this many owners already carry today's registration date is rejected with a
102	     * 429 Too Many Requests.
103	     */
104	    private static final int MAX_OWNERS_PER_DAY = 100;
105	
106	    /**
107	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
108	     * owners already carry the new owner's registration date, the created owner is flagged
109	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
110	     */
111	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
112	
113	    /**
114	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
115	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
116	     */
117	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
118	        "ST", "STREET",
119	        "RD", "ROAD",
120	        "AVE", "AVENUE");
121	
122	    public OwnerRestControllerV1(ClinicService clinicService,
123	                                 OwnerMapper ownerMapper,
124	                                 PetMapper petMapper,
125	                                 VisitMapper visitMapper) {
126	        this.clinicService = clinicService;
127	        this.ownerMapper = ownerMapper;
128	        this.petMapper = petMapper;
129	        this.visitMapper = visitMapper;
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
135	        Collection<Owner> owners;
136	        if (lastName != null) {
137	            owners = this.clinicService.findOwnerByLastName(lastName);
138	        } else {
139	            owners = this.clinicService.findAllOwners();
140	        }
141	        if (owners.isEmpty()) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
150	        Owner owner = this.clinicService.findOwnerById(ownerId);
151	        if (owner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
160	        validateRequiredFields(ownerFieldsDto);
161	        HttpHeaders headers = new HttpHeaders();
162	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
163	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
164	        owner.setRegistrationDate(registrationDate);
165	        requireDailyCapacity(registrationDate);
166	        requireCityHasCapacity(owner.getCity());
167	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
168	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
169	            joinHousehold(owner);
170	        } else {
171	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
172	        }
173	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
174	        requireUniqueTelephone(telephone);
175	        owner.setTelephone(telephone);
176	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
177	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
178	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
179	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
180	        this.clinicService.saveOwner(owner);
181	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
182	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
183	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
184	        headers.setLocation(UriComponentsBuilder.newInstance()
185	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
186	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
187	    }
188	
189	    /**
190	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
191	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
192	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
193	     * existed prior to this create.
194	     *
195	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
196	     *     a business day
197	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
198	     *     registered on that business day
199	     */
200	    private void requireDailyCapacity(LocalDate registrationDate) {
201	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
202	            throw new DailyOwnerLimitException(registrationDate);
203	        }
204	    }
205	
206	    /**
207	     * Counts the existing owners whose registration date equals the given business-day date. This is
208	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
209	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
210	     * the bulk-signup warning.
211	     *
212	     * @param registrationDate the effective business-day registration date to count against
213	     * @return the number of pre-existing owners registered on that date
214	     */
215	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
216	        return this.clinicService.findAllOwners().stream()
217	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
218	            .count();
219	    }
220	
221	    /**
222	     * Rejects an owner whose city already contains the maximum allowed number of owners
223	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
224	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
225	     * create.
226	     *
227	     * @param city the city of the owner being created
228	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
229	     */
230	    private void requireCityHasCapacity(String city) {
231	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
232	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
233	            .count();
234	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
235	            throw new CityOwnerLimitException(city);
236	        }
237	    }
238	
239	    /**
240	     * Generates the customer code for a newly created owner, formatted
241	     * {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3} is the upper-cased first three letters of the
242	     * city, {@code LAST3} the upper-cased first three letters of the last name, and {@code NNNN} a
243	     * per-city, 4-digit zero-padded sequence equal to one more than the number of owners already in
244	     * that city (e.g. {@code 'LON-SMI-0007'}).
245	     *
246	     * @param city the owner's city
247	     * @param lastName the owner's last name
248	     * @return the generated customer code
249	     */
250	    private String generateCustomerCode(String city, String lastName) {
251	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
252	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
253	        int sequence = (int) this.clinicService.findAllOwners().stream()
254	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
255	            .count() + 1;
256	        return String.format("%s-%s-%04d", city3, last3, sequence);
257	    }
258	
259	    /**
260	     * Counts the existing owners that already share the given first name and last name, compared
261	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
262	     * owners that existed prior to this create.
263	     *
264	     * @param firstName the first name of the owner being created
265	     * @param lastName the last name of the owner being created
266	     * @return the number of pre-existing namesakes
267	     */
268	    private int countNamesakes(String firstName, String lastName) {
269	        return (int) this.clinicService.findAllOwners().stream()
270	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
271	                && equalsIgnoreCase(existing.getLastName(), lastName))
272	            .count();
273	    }
274	
275	    /**
276	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
277	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
278	     *
279	     * @param a the first value, possibly {@code null}
280	     * @param b the second value, possibly {@code null}
281	     * @return whether the values are equal ignoring case
282	     */
283	    private boolean equalsIgnoreCase(String a, String b) {
284	        return a == null ? b == null : a.equalsIgnoreCase(b);
285	    }
286	
287	    /**
288	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
289	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
290	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
291	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
292	     *
293	     * @param ownerFieldsDto the submitted owner fields
294	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
295	     */
296	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
297	        List<String> invalidFields = new ArrayList<>();
298	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
299	            invalidFields.add("firstName");
300	        }
301	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
302	            invalidFields.add("lastName");
303	        }
304	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
305	            invalidFields.add("address");
306	        }
307	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
308	            invalidFields.add("city");
309	        }
310	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
311	            invalidFields.add("telephone");
312	        }
313	        if (!invalidFields.isEmpty()) {
314	            throw new InvalidOwnerFieldsException(invalidFields);
315	        }
316	    }
317	
318	    /**
319	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
320	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
321	     * what gets stored and returned.
322	     *
323	     * @param telephone the raw telephone value from the request
324	     * @return the normalized E.164 telephone number
325	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
326	     */
327	    private String normalizeTelephone(String telephone) {
328	        String e164 = toE164(telephone);
329	        if (e164 == null) {
330	            throw new InvalidOwnerFieldsException(List.of("telephone"));
331	        }
332	        return e164;
333	    }
334	
335	    /**
336	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
337	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
338	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
339	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
340	     * it contains 8 to 15 digits after the {@code '+'}.
341	     *
342	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
343	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
344	     *
345	     * @param telephone the raw telephone value, possibly {@code null}
346	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
347	     */
348	    private String toE164(String telephone) {
349	        if (telephone == null) {
350	            return null;
351	        }
352	        String cleaned = telephone.replaceAll("[ \\-()]", "");
353	        String digits;
354	        if (cleaned.startsWith("+")) {
355	            digits = cleaned.substring(1);
356	        } else {
357	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
358	            digits = "61" + national;
359	        }
360	        if (!digits.matches("[0-9]{8,15}")) {
361	            return null;
362	        }
363	        return "+" + digits;
364	    }
365	
366	    /**
367	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
368	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
369	     * and returned lower-cased.
370	     *
371	     * @param email the raw email value from the request, possibly {@code null}
372	     * @return the lower-cased email, or {@code null} when none was supplied
373	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
374	     */
375	    private String normalizeEmail(String email) {
376	        if (!StringUtils.hasText(email)) {
377	            return null;
378	        }
379	        String trimmed = email.trim();
380	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
381	            throw new InvalidOwnerFieldsException(List.of("email"));
382	        }
383	        return trimmed.toLowerCase(Locale.ROOT);
384	    }
385	
386	    /**
387	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
388	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
389	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
390	     *
391	     * @param telephone the normalized (E.164) telephone of the owner being created
392	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
393	     */
394	    private void requireUniqueTelephone(String telephone) {
395	        boolean inUse = this.clinicService.findAllOwners().stream()
396	            .map(Owner::getTelephone)
397	            .filter(existing -> existing != null)
398	            .map(existing -> {
399	                String e164 = toE164(existing);
400	                return e164 != null ? e164 : existing;
401	            })
402	            .anyMatch(telephone::equals);
403	        if (inUse) {
404	            throw new DuplicateTelephoneException(telephone);
405	        }
406	    }
407	
408	    /**
409	     * Rejects an owner whose last name and address match those of an existing owner, where both are
410	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
411	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
412	     *
413	     * @param lastName the last name of the owner being created
414	     * @param address the address of the owner being created
415	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
416	     */
417	    private void requireUniqueHousehold(String lastName, String address) {
418	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
419	            throw new DuplicateHouseholdException(lastName, address);
420	        }
421	    }
422	
423	    /**
424	     * Returns the existing owners that belong to the same household as the given last name and
425	     * address, i.e. those whose last name and address match case-insensitively and with runs of
426	     * whitespace collapsed to a single space.
427	     *
428	     * @param lastName the last name to match
429	     * @param address the address to match
430	     * @return the matching owners (possibly empty, never {@code null})
431	     */
432	    private List<Owner> findHouseholdMembers(String lastName, String address) {
433	        String normalizedLastName = normalizeForHousehold(lastName);
434	        String normalizedAddress = normalizeAddress(address);
435	        return this.clinicService.findAllOwners().stream()
436	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
437	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
438	            .toList();
439	    }
440	
441	    /**
442	     * Joins the owner being created to the shared household of any existing owner(s) that have the
443	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
444	     * member of the household - the existing owners and the new one - is assigned the same stable
445	     * {@code householdId}, so the shared identifier can be read back from any of them.
446	     *
447	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
448	     * the owner is left without a {@code householdId}.
449	     *
450	     * <p>Every member of the household - the existing owners and the new one - is also stamped with
451	     * the household's member count after this create ({@code householdSize}), so the shared size can
452	     * be read back from any of them.
453	     *
454	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
455	     */
456	    private void joinHousehold(Owner owner) {
457	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
458	        if (members.isEmpty()) {
459	            return;
460	        }
461	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
462	        int householdSize = members.size() + 1;
463	        owner.setHouseholdId(householdId);
464	        owner.setHouseholdSize(householdSize);
465	        for (Owner member : members) {
466	            member.setHouseholdId(householdId);
467	            member.setHouseholdSize(householdSize);
468	            this.clinicService.saveOwner(member);
469	        }
470	    }
471	
472	    /**
473	     * Computes the stable, shared household identifier for a last name and address. The value is
474	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
475	     * name and address, so every owner in the same household computes the same identifier.
476	     *
477	     * @param lastName the last name of the household
478	     * @param address the address of the household
479	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
480	     */
481	    private String computeHouseholdId(String lastName, String address) {
482	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
483	        try {
484	            byte[] digest = MessageDigest.getInstance("SHA-256")
485	                .digest(key.getBytes(StandardCharsets.UTF_8));
486	            StringBuilder hex = new StringBuilder();
487	            for (int i = 0; i < 6; i++) {
488	                hex.append(String.format("%02X", digest[i]));
489	            }
490	            return "HH-" + hex;
491	        } catch (NoSuchAlgorithmException e) {
492	            throw new IllegalStateException("SHA-256 algorithm not available", e);
493	        }
494	    }
495	
496	    /**
497	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
498	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
499	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
500	     *
501	     * @param value the raw value, possibly {@code null}
502	     * @return the normalized value
503	     */
504	    private String normalizeForHousehold(String value) {
505	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
506	    }
507	
508	    /**
509	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
510	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
511	     * value yields an empty string.
512	     *
513	     * @param value the raw value, possibly {@code null}
514	     * @return the trimmed, whitespace-collapsed value
515	     */
516	    private String collapseWhitespace(String value) {
517	        if (value == null) {
518	            return "";
519	        }
520	        return value.trim().replaceAll("\\s+", " ");
521	    }
522	
523	    /**
524	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
525	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
526	     * is upper-cased, and common street-type abbreviations are expanded as whole words
527	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
528	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
529	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
530	     *
531	     * @param address the raw address value, possibly {@code null}
532	     * @return the normalized address
533	     */
534	    private String normalizeAddress(String address) {
535	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
536	        if (collapsed.isEmpty()) {
537	            return "";
538	        }
539	        String[] tokens = collapsed.split(" ");
540	        StringBuilder normalized = new StringBuilder();
541	        for (int i = 0; i < tokens.length; i++) {
542	            if (i > 0) {
543	                normalized.append(' ');
544	            }
545	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
546	        }
547	        return normalized.toString();
548	    }
549	
550	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
551	    @Override
552	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
553	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
554	        if (currentOwner == null) {
555	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
556	        }
557	        currentOwner.setAddress(ownerFieldsDto.getAddress());
558	        currentOwner.setCity(ownerFieldsDto.getCity());
559	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
560	        currentOwner.setLastName(ownerFieldsDto.getLastName());
561	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
562	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
563	        this.clinicService.saveOwner(currentOwner);
564	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
565	    }
566	
567	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
568	    @Transactional
569	    @Override
570	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
571	        Owner owner = this.clinicService.findOwnerById(ownerId);
572	        if (owner == null) {
573	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
574	        }
575	        this.clinicService.deleteOwner(owner);
576	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
577	    }
578	
579	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
580	    @Override
581	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
582	        Owner owner = this.clinicService.findOwnerById(ownerId);
583	        if (owner == null) {
584	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
585	        }
586	        HttpHeaders headers = new HttpHeaders();
587	        Pet pet = petMapper.toPet(petFieldsDto);
588	        owner.setId(ownerId);
589	        pet.setOwner(owner);
590	        pet.getType().setName(null);
591	        this.clinicService.savePet(pet);
592	        PetDto petDto = petMapper.toPetDto(pet);
593	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
594	            .buildAndExpand(pet.getId()).toUri());
595	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
596	    }
597	
598	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
599	    @Override
600	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
601	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
602	        if (currentOwner != null) {
603	            Pet currentPet = this.clinicService.findPetById(petId);
604	            if (currentPet != null) {
605	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
606	                currentPet.setName(petFieldsDto.getName());
607	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
608	                this.clinicService.savePet(currentPet);
609	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
610	            }
611	        }
612	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
613	    }
614	
615	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
616	    @Override
617	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
618	        HttpHeaders headers = new HttpHeaders();
619	        Visit visit = visitMapper.toVisit(visitFieldsDto);
620	        Pet pet = new Pet();
621	        pet.setId(petId);
622	        visit.setPet(pet);
623	        this.clinicService.saveVisit(visit);
624	        VisitDto visitDto = visitMapper.toVisitDto(visit);
625	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
626	            .buildAndExpand(visit.getId()).toUri());
627	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
628	    }
629	
630	
631	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
632	    @Override
633	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
634	        Owner owner = this.clinicService.findOwnerById(ownerId);
635	        if (owner != null) {
636	            Pet pet = owner.getPet(petId);
637	            if (pet != null) {
638	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
639	            }
640	        }
641	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
642	    }
643	}
