27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "household_size")
67	    private Integer householdSize;
68	
69	    @Column(name = "bulk_signup_warning")
70	    private Boolean bulkSignupWarning;
71	
72	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
73	    private Set<Pet> pets;
74	
75	    /**
76	     * Fixed city-to-region table used to derive {@link #getLocality() locality}. Any city not
77	     * listed derives the locality {@code 'UNKNOWN'}.
78	     */
79	    private static final Map<String, String> CITY_REGION = Map.of(
80	        "Sydney", "NSW",
81	        "Melbourne", "VIC",
82	        "Brisbane", "QLD");
83	
84	    public String getAddress() {
85	        return this.address;
86	    }
87	
88	    public void setAddress(String address) {
89	        this.address = address;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    public String getTelephone() {
101	        return this.telephone;
102	    }
103	
104	    public void setTelephone(String telephone) {
105	        this.telephone = telephone;
106	    }
107	
108	    public String getEmail() {
109	        return this.email;
110	    }
111	
112	    public void setEmail(String email) {
113	        this.email = email;
114	    }
115	
116	    public LocalDate getRegistrationDate() {
117	        return this.registrationDate;
118	    }
119	
120	    public void setRegistrationDate(LocalDate registrationDate) {
121	        this.registrationDate = registrationDate;
122	    }
123	
124	    public String getCustomerCode() {
125	        return this.customerCode;
126	    }
127	
128	    public void setCustomerCode(String customerCode) {
129	        this.customerCode = customerCode;
130	    }
131	
132	    /**
133	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
134	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}). Derived
135	     * from the owner's own customer code and registration date; {@code null} when either is absent.
136	     *
137	     * @return the membership number, or {@code null} when it cannot be derived
138	     */
139	    public String getMembershipNumber() {
140	        if (this.customerCode == null || this.registrationDate == null) {
141	            return null;
142	        }
143	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
144	    }
145	
146	    /**
147	     * The owner's numeric membership level, derived from the values frozen at create time. It starts
148	     * at 1, gains 1 when an email address is present, gains 1 when the owner has no namesakes
149	     * ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
150	     *
151	     * @return the membership level, an integer from 1 to 3
152	     */
153	    public Integer getMembershipLevel() {
154	        int level = 1;
155	        boolean hasEmail = this.email != null && !this.email.isBlank();
156	        if (hasEmail) {
157	            level++;
158	        }
159	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
160	        if (hasNoNamesakes) {
161	            level++;
162	        }
163	        return Math.min(level, 3);
164	    }
165	
166	    /**
167	     * The owner's locality, derived from the {@link #getCity() city} using the fixed
168	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). Returns the canonical
169	     * region string, or {@code 'UNKNOWN'} when the city is absent or not in the table.
170	     *
171	     * @return the canonical region string, or {@code 'UNKNOWN'}
172	     */
173	    public String getLocality() {
174	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
175	    }
176	
177	    public String getHouseholdId() {
178	        return this.householdId;
179	    }
180	
181	    public void setHouseholdId(String householdId) {
182	        this.householdId = householdId;
183	    }
184	
185	    public Integer getNamesakeCount() {
186	        return this.namesakeCount;
187	    }
188	
189	    public void setNamesakeCount(Integer namesakeCount) {
190	        this.namesakeCount = namesakeCount;
191	    }
192	
193	    public Integer getHouseholdSize() {
194	        return this.householdSize;
195	    }
196	
197	    public void setHouseholdSize(Integer householdSize) {
198	        this.householdSize = householdSize;
199	    }
200	
201	    public Boolean getBulkSignupWarning() {
202	        return this.bulkSignupWarning;
203	    }
204	
205	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
206	        this.bulkSignupWarning = bulkSignupWarning;
207	    }
208	
209	    /**
210	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
211	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
212	     */
213	    @PrePersist
214	    void onCreate() {
215	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
216	    }
217	
218	    /**
219	     * Resolves the effective registration date and rolls it onto a business day. An absent
220	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
221	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
222	     * becomes the following Monday, while any weekday is returned unchanged.
223	     *
224	     * <p>This is the single definition of both the defaulting and the business-day roll, used
225	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
226	     * stamps the owner and by the create endpoint that counts owners per business day.
227	     *
228	     * @param supplied the registration date from the request, or {@code null} when none was supplied
229	     * @return the effective registration date, guaranteed to fall on a business day
230	     */
231	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
232	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
233	        return switch (effective.getDayOfWeek()) {
234	            case SATURDAY -> effective.plusDays(2);
235	            case SUNDAY -> effective.plusDays(1);
236	            default -> effective;
237	        };
238	    }
239	
240	    protected Set<Pet> getPetsInternal() {
241	        if (this.pets == null) {
242	            this.pets = new HashSet<>();
243	        }
244	        return this.pets;
245	    }
246	
247	    protected void setPetsInternal(Set<Pet> pets) {
248	        this.pets = pets;
249	    }
250	
251	    public List<Pet> getPets() {
252	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
253	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
254	        return Collections.unmodifiableList(sortedPets);
255	    }
256	
257	    public void setPets(List<Pet> pets) {
258	        this.pets = new HashSet<>(pets);
259	    }
260	
261	    public void addPet(Pet pet) {
262	        getPetsInternal().add(pet);
263	        pet.setOwner(this);
264	    }
265	
266	    /**
267	     * Return the Pet with the given name, or null if none found for this Owner.
268	     *
269	     * @param name to test
270	     * @return true if pet name is already in use
271	     */
272	    public Pet getPet(String name) {
273	        return getPet(name, false);
274	    }
275	
276	    /**
277	     * Return the Pet with the given name, or null if none found for this Owner.
278	     *
279	     * @param name to test
280	     * @return true if pet name is already in use
281	     */
282	    public Pet getPet(String name, boolean ignoreNew) {
283	        name = name.toLowerCase();
284	        for (Pet pet : getPetsInternal()) {
285	            if (!ignoreNew || !pet.isNew()) {
286	                String compName = pet.getName();
287	                compName = compName.toLowerCase();
288	                if (compName.equals(name)) {
289	                    return pet;
290	                }
291	            }
292	        }
293	        return null;
294	    }
295	
296	    public Pet getPet(Integer petId) {
297	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
298	    }
299	
300	    @Override
301	    public String toString() {
302	        return new ToStringCreator(this)
303	
304	            .append("id", this.getId())
305	            .append("new", this.isNew())
306	            .append("lastName", this.getLastName())
307	            .append("firstName", this.getFirstName())
308	            .append("address", this.address)
309	            .append("city", this.city)
310	            .append("telephone", this.telephone)
311	            .toString();
312	    }
313	}
